import{_ as p,a0 as n,w as i,s as d,I as s,x as a,a1 as l,A as r,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何在 Linux 上用 SQL 語句來查詢 Apache 日誌 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上用 SQL 語句來查詢 Apache 日誌 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上用 SQL 語句來查詢 Apache 日誌 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上用 SQL 語句來查詢 Apache 日誌 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141030 How to run SQL queries against Apache log files on Linux","title":"如何在 Linux 上用 SQL 語句來查詢 Apache 日誌","tag":"201412","desc":""},"relativePath":"201412/20141030 How to run SQL queries against Apache log files on Linux.md","filePath":"[post].md"}'),c={name:"201412/20141030 How to run SQL queries against Apache log files on Linux.md"};function u(g,e,m,h,f,q){const t=n("Link");return i(),d("div",null,[e[19]||(e[19]=s("h1",{id:"如何在-linux-上用-sql-語句來查詢-apache-日誌",tabindex:"-1"},[a("如何在 Linux 上用 SQL 語句來查詢 Apache 日誌 "),s("a",{class:"header-anchor",href:"#如何在-linux-上用-sql-語句來查詢-apache-日誌","aria-label":"Permalink to “如何在 Linux 上用 SQL 語句來查詢 Apache 日誌”"},"​")],-1)),e[20]||(e[20]=s("p",null,"Linux 有一個顯著的特點，在正常情況下，你可以通過日誌分析系統日誌來了解你的系統中發生了什麼，或正在發生什麼。的確，系統日誌是系統管理員在解決系統和應用問題時最需要的第一手資源。我們將在這篇文章中着重講解 Apache HTTP web server 生成的 Apache access 日誌。",-1)),s("p",null,[e[1]||(e[1]=a("這次，我們會通過另類的途徑來分析 Apache access 日誌，我們使用的工具是 ",-1)),l(t,{href:"http://www.steve.org.uk/Software/asql/"},{default:r(()=>[...e[0]||(e[0]=[a("asql",-1)])]),_:1}),e[2]||(e[2]=a("。asql 是一個開源的工具，它能夠允許使用者使用 SQL 語句來查詢日誌，從而通過更加友好的格式展現相同的信息。",-1))]),e[21]||(e[21]=o(`<h3 id="apache-日誌背景知識" tabindex="-1">Apache 日誌背景知識 <a class="header-anchor" href="#apache-日誌背景知識" aria-label="Permalink to “Apache 日誌背景知識”">​</a></h3><p>Apache 有兩種日誌：</p><ul><li><strong>Access log</strong>：存放在路徑 /var/log/apache2/access.log (Debian) 或者 /var/log/httpd/access_log (Red Hat)。Access Log 記錄所有 Apache web server 執行的請求。</li><li><strong>Error log</strong>：存放在路徑 /var/log/apache2/error.log (Debian) 或者 /var/log/httpd/error_log (Red Hat)。Error log 記錄所有 Apache web server 報告的錯誤以及錯誤的情況。Error 情況包括（不限於）403（Forbidden，通常在請求被拒絕訪問時被報告），404（Not found，在請求資源不存在時被報告）。</li></ul><p>雖然管理員可以通過配置 Apache 的配置文件來自定義 Apache access log 的詳細程度，不過在這篇文章中，我們會使用默認的配置，如下：</p><pre><code>遠程 IP - 請求時間 - 請求類型 - 響應代碼 - 請求的 URL - 遠程的瀏覽器信息 (也許包含操作系統信息)
</code></pre><p>因此一個典型的 Apache 日誌條目就是下面這個樣子：</p><pre><code>192.168.0.101 - - [22/Aug/2014:12:03:36 -0300] &quot;GET /icons/unknown.gif HTTP/1.1&quot; 200 519 &quot;http://192.168.0.10/test/projects/read_json/&quot; &quot;Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:30.0) Gecko/20100101 Firefox/30.0&quot;
</code></pre><p>但是 Apache error log 又是怎麼樣的呢？因為 error log 條目主要記錄 access log 中特殊的請求（你可以自定義），所以你可以通過 access log 來獲得關於錯誤情況的更多信息（example 5 有更多細節）。</p><p>此外要提前説明的， access log 是系統級別的日誌文件。要分析虛擬主機的日誌文件，你需要檢查它們相應的配置文件（例如： 在 /etc/apache2/sites-available/[virtual host name] 裏（Debian））。</p><h3 id="在-linux-上安裝-asql" tabindex="-1">在 Linux 上安裝 asql <a class="header-anchor" href="#在-linux-上安裝-asql" aria-label="Permalink to “在 Linux 上安裝 asql”">​</a></h3><p>asql 由 Perl 編寫，而且需求以下兩個 Perl 模組：SQLite 的 DBI 驅動以及 GNU readline。</p><h3 id="在-debian-ubuntu-以及其衍生發行版上安裝-asql" tabindex="-1">在 Debian, Ubuntu 以及其衍生發行版上安裝 asql <a class="header-anchor" href="#在-debian-ubuntu-以及其衍生發行版上安裝-asql" aria-label="Permalink to “在 Debian, Ubuntu 以及其衍生發行版上安裝 asql”">​</a></h3><p>使用基於 Debian 發行版上的 aptitude，asql 以及其依賴會被自動安裝。</p><pre><code># aptitude install asql
</code></pre><h3 id="在-fedora-centos-rhel-上安裝-asql" tabindex="-1">在 Fedora，CentOS，RHEL 上安裝 asql <a class="header-anchor" href="#在-fedora-centos-rhel-上安裝-asql" aria-label="Permalink to “在 Fedora，CentOS，RHEL 上安裝 asql”">​</a></h3>`,15)),s("p",null,[e[4]||(e[4]=a("在 CentOS 或 RHEL 上，你需要啓用 ",-1)),l(t,{href:"http://xmodulo.com/how-to-set-up-epel-repository-on-centos.html"},{default:r(()=>[...e[3]||(e[3]=[a("EPEL repository",-1)])]),_:1}),e[5]||(e[5]=a("，然後運行以下代碼。在 Fedora 中，直接運行以下代碼：",-1))]),e[22]||(e[22]=o(`<pre><code># sudo yum install perl-DBD-SQLite perl-Term-Readline-Gnu
# wget http://www.steve.org.uk/Software/asql/asql-1.7.tar.gz
# tar xvfvz asql-1.7.tar.gz
# cd asql
# make install
</code></pre><h3 id="asql-是如何工作的" tabindex="-1">asql 是如何工作的？ <a class="header-anchor" href="#asql-是如何工作的" aria-label="Permalink to “asql 是如何工作的？”">​</a></h3><p>從上面代碼中的依賴中你就可以看出來，asql 轉換未結構化的明文 Apache 日誌為結構化的 SQLite 資料庫信息。生成的 SQLite 資料庫可以接受正常的 SQL 查詢語句。資料庫可以通過當前以及之前的日誌文件生成，其中也包括壓縮轉換過的日誌文件，類似 access.log.X.gz 或者 access_log.old。</p><p>首先，從命令列啓動 asql：</p><pre><code># asql
</code></pre><p>你會進入 asql 內置的 shell 交互界面。</p><p><img src="https://farm8.staticflickr.com/7493/15477783969_ebedc61afc_o.png" alt=""></p><p>輸入 help 列表可執行的命令：</p><p><img src="https://farm8.staticflickr.com/7471/15478852650_ffed84ddc2_o.png" alt=""></p><p>首先在 asql 中加載所有的 access 日誌：</p><pre><code>asql &gt; load &lt;apache-access-logs 的路徑&gt;
</code></pre><p>比如在 Debian 下：</p><pre><code>asql &gt; load /var/log/apache2/access.*
</code></pre><p>在 CentOS/RHEL 下：</p><pre><code>asql &gt; load /var/log/httpd/access_log*
</code></pre><p>當 asql 完成對 access 日誌的加載後，我們就可以開始資料庫查詢了。注意一下，加載後生成的資料庫是 &quot;temporary&quot; （臨時）的，意思就是資料庫會在你退出 asql 的時候被清除。如果你想要保留資料庫，你必須先將其保存為一個文件。我們會在後面介紹如何這麼做（參考 example 3 和 4）。</p><p><img src="https://farm8.staticflickr.com/7489/15044293173_f21e38692b_o.png" alt=""></p><p>生成的資料庫有一個名為 logs 的表。輸入下面的命令列出 logs 表中提供的域：</p><p><img src="https://farm4.staticflickr.com/3955/15664433685_465e8f47bd_o.png" alt=""></p><p>一個名為 .asql 的隱藏文件，保存於用户的 home 目錄下，記錄用户在 asql shell 中輸入的命令歷史。因此你可以使用方向鍵瀏覽命令歷史，按下 ENTER 來重複執行之前的命令。</p><h3 id="asql-上的示例-sql-查詢" tabindex="-1">asql 上的示例 SQL 查詢 <a class="header-anchor" href="#asql-上的示例-sql-查詢" aria-label="Permalink to “asql 上的示例 SQL 查詢”">​</a></h3><p>下面是幾個使用 asql 針對 Apache 日誌文件運行 SQL 查詢的示例：</p><p><strong>Example 1</strong>：列出在 2014 年 10 月中請求的來源 / 時間以及 HTTP 狀態碼。</p><pre><code>SELECT source, date, status FROM logs WHERE date &gt;= &#39;2014-10-01T00:00:00&#39; ORDER BY source;
</code></pre><p><img src="https://farm8.staticflickr.com/7488/15664433665_dde4ac1319_z.jpg" alt=""></p><p><strong>Example 2</strong>：從小到大顯示單個客户端處理的請求大小（bytes）。</p><pre><code>SELECT source, SUM(size), AS NUMBER FROM logs GROUP BY source ORDER BY Number DESC;
</code></pre><p><img src="https://farm4.staticflickr.com/3938/15478271548_369541b56c_z.jpg" alt=""></p><p><strong>Example 3</strong>：在當前目錄中保存資料庫為 [filename]。</p><pre><code>save [filename]
</code></pre><p><img src="https://farm8.staticflickr.com/7576/15664433645_16510d8938_o.png" alt=""></p><p>這樣做可以避免使用 load 命令對日誌的語法分析所佔用的處理時間。</p><p><strong>Example 4</strong>：在重新進入 asql 後載入資料庫。</p><pre><code>restore [filename]
</code></pre><p><img src="https://farm4.staticflickr.com/3941/15664433635_737e714780_o.png" alt=""></p><p><strong>Example 5</strong>：返回 access 日誌中記錄的 error 情況。在這個例子中，我們將顯示所有返回 HTTP 狀態碼為 403（access forbidden）的請求。</p><pre><code>SELECT source, date, status, request FROM logs WHERE status=&#39;403&#39; ORDER BY date
</code></pre><p><img src="https://farm8.staticflickr.com/7551/15478271518_0444582a3d_z.jpg" alt=""></p><p>這個例子想要表現的是：雖然 asql 只分析 access 日誌，我們還是可以通過使用請求的狀態域來顯示有 error 情況的請求。</p><h3 id="小結" tabindex="-1">小結： <a class="header-anchor" href="#小結" aria-label="Permalink to “小結：”">​</a></h3><p>我們體驗了 asql 如何幫助我們分析 Apache 日誌文件，並將結果通過友好的格式輸出。雖然你也可以通過使用命令列的工具（例如 cat 與 grep，uniq，sort，wc 等等之間的管道）來實現類似功能，與此比較起來 asql 展示了它如同瑞士軍刀一般的強大功能，使我們在自己的需求下能夠通過標準 SQL 查詢語句來過濾日誌。</p><p>希望這篇教程能幫助到你們。</p><p>請不要拘束地將評論文章，分享文章，提出疑問。</p><hr>`,44)),s("p",null,[e[7]||(e[7]=a("via: ",-1)),l(t,{href:"http://xmodulo.com/sql-queries-apache-log-files-linux.html"},{default:r(()=>[...e[6]||(e[6]=[a("http://xmodulo.com/sql-queries-apache-log-files-linux.html",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=a("作者：",-1)),l(t,{href:"http://xmodulo.com/author/gabriel"},{default:r(()=>[...e[8]||(e[8]=[a("Gabriel Cánepa",-1)])]),_:1}),e[12]||(e[12]=a(" 譯者：",-1)),l(t,{href:"https://github.com/ThomazL"},{default:r(()=>[...e[9]||(e[9]=[a("ThomazL",-1)])]),_:1}),e[13]||(e[13]=a(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[10]||(e[10]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[16]||(e[16]=a("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[14]||(e[14]=[a("LCTT",-1)])]),_:1}),e[17]||(e[17]=a(" 原創翻譯，",-1)),l(t,{href:"http://linux.cn/"},{default:r(()=>[...e[15]||(e[15]=[a("Linux中國",-1)])]),_:1}),e[18]||(e[18]=a(" 榮譽推出",-1))])])}const T=p(c,[["render",u]]);export{b as __pageData,T as default};
